SELECT id, type, sender, receiver, subject, content, channel, state, org_id as orgId, business_id as businessId, priority, is_read as isRead, create_time as createTime, read_time as readTime, create_by as createBy, update_by as updateBy, is_deleted as deleted, update_time as updateTime FROM internal_message WHERE receiver = #{userId} AND org_id = #{orgId} AND is_deleted = FALSE
AND is_read = #{isRead}
ORDER BY create_time DESC
LIMIT #{limit}

